package com.example.sgva.domain

/**
 * Reglas de formato compartidas por las entidades del dominio. Centraliza la
 * verificación del formato `AAAAS` para que `Estudiante.cohorte` y
 * `Docente.periodo` apliquen exactamente el mismo criterio.
 */
internal object ReglasDeFormato {

    /** Regex de referencia definida en `DESIGN_SGVA.md`, Sección 0.1. */
    private val PATRON_PERIODO_ACADEMICO = Regex("""^\d{4}[12]$""")

    /**
     * Verifica que [valor] cumpla el formato `AAAAS` y lo devuelve sin cambios.
     *
     * @throws FormatoPeriodoInvalidoException si el formato no es válido.
     */
    fun exigirPeriodoAcademico(valor: String, campo: String): String {
        if (!PATRON_PERIODO_ACADEMICO.matches(valor)) {
            throw FormatoPeriodoInvalidoException(campo, valor)
        }
        return valor
    }

    /**
     * Verifica que [valor] no esté vacío ni en blanco y lo devuelve sin cambios.
     *
     * @throws CampoRequeridoVacioException si el valor está en blanco.
     */
    fun exigirNoVacio(valor: String, campo: String): String {
        if (valor.isBlank()) {
            throw CampoRequeridoVacioException(campo)
        }
        return valor
    }
}

package com.example.sgva.domain

/**
 * Indicador cuantitativo de calidad, resultado consolidado de los casos de uso
 * de los Módulos 1 y 2 (`DESIGN_SGVA.md` §1). Es el output principal que consume
 * el Dashboard.
 *
 * @property nombre nombre del indicador (ej.: "Tasa de Deserción", "Promedio Saber Pro").
 * @property valor resultado numérico calculado; debe ser un número finito.
 * @property periodo periodo académico `AAAAS` al que corresponde el valor, o
 *   [CONSOLIDADO] cuando el indicador agrega todos los periodos.
 * @property facultad facultad a la que corresponde, o [TODAS_LAS_FACULTADES]
 *   cuando el indicador no se filtró por facultad.
 */
data class IndicadorCalidad(
    val nombre: String,
    val valor: Double,
    val periodo: String,
    val facultad: String,
) {
    init {
        ReglasDeFormato.exigirNoVacio(nombre, "nombre")
        ReglasDeFormato.exigirNoVacio(periodo, "periodo")
        ReglasDeFormato.exigirNoVacio(facultad, "facultad")
        if (!valor.isFinite()) {
            throw ValorIndicadorInvalidoException(nombre, valor)
        }
    }

    companion object {
        /** Valor de [periodo] cuando el indicador agrega todos los periodos académicos. */
        const val CONSOLIDADO: String = "CONSOLIDADO"

        /** Valor de [facultad] cuando el indicador no se filtró por facultad. */
        const val TODAS_LAS_FACULTADES: String = "TODAS"

        /** Nombres canónicos de los indicadores del Módulo 1 (`DESIGN_SGVA.md` §1). */
        const val EVOLUCION_MATRICULA: String = "Evolución de Matrícula"
        const val TASA_DESERCION: String = "Tasa de Deserción"
        const val PROMEDIO_SABER_PRO: String = "Promedio Saber Pro"

        /** Nombres canónicos de los indicadores del Módulo 2 (`DESIGN_SGVA.md` §1). */
        const val DISTRIBUCION_FORMACION: String = "Distribución de Formación"
        const val RELACION_ESTUDIANTE_PROFESOR: String = "Relación Estudiante/Profesor"

        /** Nombre del indicador de distribución para un nivel de formación concreto. */
        fun distribucionFormacionPara(nivel: String): String = "$DISTRIBUCION_FORMACION - $nivel"
    }
}

package com.example.sgva.usecases

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.EntidadDuplicadaException
import com.example.sgva.domain.Estudiante

/**
 * Registra un nuevo estudiante en el sistema (Factor 2).
 *
 * La validación de formato y rango de los campos ya está garantizada por el
 * bloque `init` de [Estudiante] (una instancia corrupta no puede construirse).
 * Este caso de uso solo aporta la regla de aplicación restante: el
 * identificador debe ser único.
 */
class RegistrarEstudianteUseCase(
    private val repositorio: AcademicDataRepository,
) {

    /**
     * Da de alta [estudiante] y lo devuelve tal como quedó persistido.
     *
     * @throws EntidadDuplicadaException si ya existe un estudiante con el mismo `id`.
     */
    fun ejecutar(estudiante: Estudiante): Estudiante {
        if (repositorio.buscarEstudiantePorId(estudiante.id) != null) {
            throw EntidadDuplicadaException("estudiante", estudiante.id)
        }
        return repositorio.guardarEstudiante(estudiante)
    }
}

package com.example.sgva.usecases

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.Docente
import com.example.sgva.domain.EntidadDuplicadaException

/**
 * Registra un nuevo docente de la planta profesoral (Factor 3).
 *
 * La validación de formato de los campos ya está garantizada por el bloque
 * `init` de [Docente]. Este caso de uso solo aporta la regla de aplicación
 * restante: el identificador debe ser único.
 */
class RegistrarDocenteUseCase(
    private val repositorio: AcademicDataRepository,
) {

    /**
     * Da de alta [docente] y lo devuelve tal como quedó persistido.
     *
     * @throws EntidadDuplicadaException si ya existe un docente con el mismo `id`.
     */
    fun ejecutar(docente: Docente): Docente {
        if (repositorio.buscarDocentePorId(docente.id) != null) {
            throw EntidadDuplicadaException("docente", docente.id)
        }
        return repositorio.guardarDocente(docente)
    }
}

package com.example.sgva.usecases

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.Estudiante

/**
 * Consulta los estudiantes registrados (Factor 2): el listado completo o uno
 * concreto por su identificador. No modifica el estado del repositorio.
 */
class ConsultarEstudiantesUseCase(
    private val repositorio: AcademicDataRepository,
) {

    /** Devuelve todos los estudiantes registrados, en orden de inserción. */
    fun listarTodos(): List<Estudiante> = repositorio.listarEstudiantes()

    /** Devuelve el estudiante con [id], o `null` si no existe ninguno con ese identificador. */
    fun buscarPorId(id: String): Estudiante? = repositorio.buscarEstudiantePorId(id)
}

package com.example.sgva.usecases

import com.example.sgva.domain.DocumentParserPort
import com.example.sgva.domain.Estudiante

/**
 * Módulo 1 — carga masiva de estudiantes desde un archivo CSV o Excel
 * (`DESIGN_SGVA.md` §2). Registra cada estudiante reutilizando
 * [RegistrarEstudianteUseCase].
 */
class ProcesarDatosEstudiantesUseCase(
    parsers: List<DocumentParserPort>,
    private val registrarEstudiante: RegistrarEstudianteUseCase,
) : ProcesarArchivoUseCase<Estudiante>(parsers) {

    override fun extraer(
        parser: DocumentParserPort,
        nombreArchivo: String,
        contenido: ByteArray,
    ): List<Estudiante> = parser.extraerEstudiantes(nombreArchivo, contenido)

    override fun idDe(entidad: Estudiante): String = entidad.id

    override fun registrar(entidad: Estudiante) {
        registrarEstudiante.ejecutar(entidad)
    }
}

package com.example.sgva.usecases

import com.example.sgva.domain.DocumentParserPort
import com.example.sgva.domain.EntidadDuplicadaException
import com.example.sgva.domain.FormatoArchivoInvalidoException
import com.example.sgva.domain.RegistroOmitido
import com.example.sgva.domain.ResultadoIngesta

/**
 * Orquestación común a las cargas masivas de archivo (`DESIGN_SGVA.md` §2):
 * elige el adaptador de parseo que soporta el archivo, le pide las entidades ya
 * normalizadas y válidas, y da de alta cada una. Un `id` ya existente —en el
 * repositorio o repetido dentro del propio archivo— se reporta como omitido en
 * lugar de abortar la carga completa.
 *
 * Las subclases solo aportan el detalle específico de la entidad: cómo pedírsela
 * al parser, cuál es su `id` y con qué caso de uso registrarla.
 */
abstract class ProcesarArchivoUseCase<T>(
    private val parsers: List<DocumentParserPort>,
) : IngestarArchivoUseCase {

    protected abstract fun extraer(
        parser: DocumentParserPort,
        nombreArchivo: String,
        contenido: ByteArray,
    ): List<T>

    protected abstract fun idDe(entidad: T): String

    protected abstract fun registrar(entidad: T)

    final override fun ejecutar(nombreArchivo: String, contenido: ByteArray): ResultadoIngesta {
        val parser = parsers.firstOrNull { it.soporta(nombreArchivo) }
            ?: throw FormatoArchivoInvalidoException(
                "El archivo '$nombreArchivo' no tiene un formato soportado (.csv, .xlsx).",
            )

        val entidades = extraer(parser, nombreArchivo, contenido)
        val omitidos = mutableListOf<RegistroOmitido>()
        var registrados = 0

        for (entidad in entidades) {
            try {
                registrar(entidad)
                registrados++
            } catch (duplicado: EntidadDuplicadaException) {
                omitidos += RegistroOmitido(idDe(entidad), duplicado.message ?: "registro duplicado")
            }
        }

        return ResultadoIngesta(
            nombreArchivo = nombreArchivo,
            totalRegistrosLeidos = entidades.size,
            registrados = registrados,
            omitidos = omitidos.toList(),
        )
    }
}

package com.example.sgva.usecases

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.Docente
import com.example.sgva.domain.Estudiante
import com.example.sgva.domain.IndicadorCalidad

/**
 * Base común de los casos de uso que producen [IndicadorCalidad] a partir de los
 * datos registrados (Módulos 1 y 2, `DESIGN_SGVA.md` §2). Centraliza el acceso
 * al repositorio, los filtros opcionales por facultad y periodo, y el redondeo
 * de los valores.
 */
abstract class CalculoDeIndicadorUseCase(
    protected val repositorio: AcademicDataRepository,
) {

    /**
     * Estudiantes registrados, opcionalmente restringidos a una [facultad]
     * (comparación sin distinguir mayúsculas y recortando espacios).
     */
    protected fun estudiantesRegistrados(facultad: String?): List<Estudiante> {
        val todos = repositorio.listarEstudiantes()
        val filtro = facultad?.trim()?.takeIf { it.isNotEmpty() } ?: return todos
        return todos.filter { it.facultad.trim().equals(filtro, ignoreCase = true) }
    }

    /**
     * Docentes registrados, opcionalmente restringidos a una [facultad] (sin
     * distinguir mayúsculas) y a un [periodo] académico exacto.
     */
    protected fun docentesRegistrados(facultad: String?, periodo: String?): List<Docente> {
        val filtroFacultad = facultad?.trim()?.takeIf { it.isNotEmpty() }
        val filtroPeriodo = periodo?.trim()?.takeIf { it.isNotEmpty() }
        return repositorio.listarDocentes().filter { docente ->
            (filtroFacultad == null || docente.facultad.trim().equals(filtroFacultad, ignoreCase = true)) &&
                (filtroPeriodo == null || docente.periodo == filtroPeriodo)
        }
    }

    /** Etiqueta de facultad para el indicador: la facultad indicada o [IndicadorCalidad.TODAS_LAS_FACULTADES]. */
    protected fun etiquetaFacultad(facultad: String?): String =
        facultad?.trim()?.takeIf { it.isNotEmpty() } ?: IndicadorCalidad.TODAS_LAS_FACULTADES

    /** Etiqueta de periodo para el indicador: el periodo indicado o [IndicadorCalidad.CONSOLIDADO]. */
    protected fun etiquetaPeriodo(periodo: String?): String =
        periodo?.trim()?.takeIf { it.isNotEmpty() } ?: IndicadorCalidad.CONSOLIDADO

    /** Fragmento " (periodo '...', facultad '...')" para los mensajes de error, o cadena vacía si no hay filtros. */
    protected fun descripcionFiltro(periodo: String?, facultad: String?): String {
        val partes = listOfNotNull(
            periodo?.trim()?.takeIf { it.isNotEmpty() }?.let { "periodo '$it'" },
            facultad?.trim()?.takeIf { it.isNotEmpty() }?.let { "facultad '$it'" },
        )
        return if (partes.isEmpty()) "" else " (" + partes.joinToString(", ") + ")"
    }

    /** Redondea a dos decimales, la precisión con la que el Dashboard muestra los indicadores. */
    protected fun redondearACentesimas(valor: Double): Double =
        Math.round(valor * 100.0) / 100.0
}

package com.example.sgva.usecases

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.DatosInsuficientesException
import com.example.sgva.domain.IndicadorCalidad
import com.example.sgva.domain.NivelFormacion

/**
 * Módulo 2 — distribución de la formación docente (`DESIGN_SGVA.md` §2).
 *
 * Agrupa los docentes por [NivelFormacion] y calcula el porcentaje que
 * representa cada nivel sobre el total, opcionalmente restringido a un periodo
 * y/o una facultad. Devuelve un [IndicadorCalidad] por cada nivel de formación
 * (incluidos los de porcentaje `0`), en el orden del enum.
 */
class CalcularDistribucionFormacionUseCase(
    repositorio: AcademicDataRepository,
) : CalculoDeIndicadorUseCase(repositorio) {

    /**
     * @throws DatosInsuficientesException si no hay docentes registrados para el filtro dado.
     */
    fun ejecutar(periodo: String? = null, facultad: String? = null): List<IndicadorCalidad> {
        val docentes = docentesRegistrados(facultad, periodo)
        if (docentes.isEmpty()) {
            throw DatosInsuficientesException(
                "No hay docentes registrados para calcular la distribución de formación" +
                    descripcionFiltro(periodo, facultad) + ".",
            )
        }

        val conteoPorNivel = docentes.groupBy { it.nivelFormacion }.mapValues { it.value.size }
        val total = docentes.size
        val etiquetaPeriodo = etiquetaPeriodo(periodo)
        val etiquetaFacultad = etiquetaFacultad(facultad)

        return NivelFormacion.entries.map { nivel ->
            IndicadorCalidad(
                nombre = IndicadorCalidad.distribucionFormacionPara(nivel.name),
                valor = redondearACentesimas(100.0 * (conteoPorNivel[nivel] ?: 0) / total),
                periodo = etiquetaPeriodo,
                facultad = etiquetaFacultad,
            )
        }
    }
}

package com.example.sgva.usecases

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.DatosInsuficientesException
import com.example.sgva.domain.EquivalenciaTiempoCompleto
import com.example.sgva.domain.EstadoEstudiante
import com.example.sgva.domain.IndicadorCalidad

/**
 * Módulo 2 — capacidad instalada / relación estudiantes-profesores
 * (`DESIGN_SGVA.md` §2).
 *
 * Calcula cuántos estudiantes matriculados hay por cada profesor de Tiempo
 * Completo Equivalente (TCE). El numerador son los estudiantes en estado
 * [EstadoEstudiante.MATRICULADO]; el denominador es la suma de los factores de
 * dedicación de los docentes ([EquivalenciaTiempoCompleto]). Ambos conjuntos se
 * pueden restringir por periodo (solo docentes) y por facultad.
 */
class CalcularCapacidadInstaladaUseCase(
    repositorio: AcademicDataRepository,
) : CalculoDeIndicadorUseCase(repositorio) {

    /**
     * @throws DatosInsuficientesException si no hay docentes (el denominador sería 0).
     */
    fun ejecutar(periodo: String? = null, facultad: String? = null): IndicadorCalidad {
        val matriculados = estudiantesRegistrados(facultad)
            .count { it.estado == EstadoEstudiante.MATRICULADO }

        val profesoresTce = docentesRegistrados(facultad, periodo)
            .sumOf { EquivalenciaTiempoCompleto.factor(it.dedicacion) }

        if (profesoresTce == 0.0) {
            throw DatosInsuficientesException(
                "No hay docentes registrados para calcular la relación estudiante/profesor" +
                    descripcionFiltro(periodo, facultad) + ".",
            )
        }

        return IndicadorCalidad(
            nombre = IndicadorCalidad.RELACION_ESTUDIANTE_PROFESOR,
            valor = redondearACentesimas(matriculados / profesoresTce),
            periodo = etiquetaPeriodo(periodo),
            facultad = etiquetaFacultad(facultad),
        )
    }
}

package com.example.sgva.infrastructure.parsing

import com.example.sgva.domain.Docente
import com.example.sgva.domain.DocumentParserPort
import com.example.sgva.domain.Estudiante
import com.example.sgva.domain.FormatoArchivoInvalidoException

/**
 * Base común de los adaptadores de [DocumentParserPort]. Concentra el
 * *Protocolo de Validación en Origen* (`DESIGN_SGVA.md` §5):
 *
 *  1. Cada adaptador concreto solo se encarga de leer el archivo a una
 *     [TablaCruda] (encabezados + filas de texto) según su formato físico.
 *  2. Esta base verifica que estén todas las columnas obligatorias de la entidad.
 *  3. Mapea y normaliza fila por fila; cualquier fallo se envuelve en
 *     [FormatoArchivoInvalidoException] indicando el archivo y la fila, sin dejar
 *     escapar excepciones técnicas de la librería de parseo.
 */
internal abstract class ParserDocumentalBase : DocumentParserPort {

    /**
     * Lee el archivo a una tabla de texto. Puede lanzar excepciones técnicas de
     * la librería subyacente: [transformar] las traduce a excepción controlada.
     */
    protected abstract fun leerTabla(contenido: ByteArray): TablaCruda

    final override fun extraerEstudiantes(nombreArchivo: String, contenido: ByteArray): List<Estudiante> =
        transformar(nombreArchivo, contenido, MapeadorEstudiante)

    final override fun extraerDocentes(nombreArchivo: String, contenido: ByteArray): List<Docente> =
        transformar(nombreArchivo, contenido, MapeadorDocente)

    private fun <T> transformar(
        nombreArchivo: String,
        contenido: ByteArray,
        mapeador: MapeadorEntidad<T>,
    ): List<T> {
        val tabla = leerTablaControlada(nombreArchivo, contenido)
        exigirColumnas(nombreArchivo, tabla.encabezados, mapeador.columnasObligatorias)

        return tabla.filas.mapIndexed { indice, valores ->
            val numeroFila = indice + 2 // +1 por el encabezado, +1 para numeración en base 1
            val fila = tabla.encabezados.zip(valores).toMap()
            try {
                mapeador.mapear(fila)
            } catch (datoInvalido: IllegalArgumentException) {
                // Cubre también NumberFormatException (subtipo) y las excepciones de dominio.
                throw FormatoArchivoInvalidoException(
                    "Archivo '$nombreArchivo', fila $numeroFila: ${datoInvalido.message}",
                    datoInvalido,
                )
            }
        }
    }

    private fun leerTablaControlada(nombreArchivo: String, contenido: ByteArray): TablaCruda =
        try {
            leerTabla(contenido)
        } catch (formatoInvalido: FormatoArchivoInvalidoException) {
            throw formatoInvalido
        } catch (falloTecnico: Exception) {
            throw FormatoArchivoInvalidoException(
                "No se pudo leer el archivo '$nombreArchivo': ${falloTecnico.message}",
                falloTecnico,
            )
        }

    private fun exigirColumnas(
        nombreArchivo: String,
        encabezados: List<String>,
        obligatorias: Set<String>,
    ) {
        val presentes = encabezados.map { it.trim() }.toSet()
        val faltantes = (obligatorias - presentes).sorted()
        if (faltantes.isNotEmpty()) {
            throw FormatoArchivoInvalidoException(
                "Al archivo '$nombreArchivo' le faltan columnas obligatorias: ${faltantes.joinToString(", ")}.",
            )
        }
    }
}

package com.example.sgva.infrastructure.parsing

import com.example.sgva.domain.FormatoArchivoInvalidoException
import de.siegmar.fastcsv.reader.CsvReader
import org.springframework.stereotype.Component
import java.io.ByteArrayInputStream
import java.nio.charset.StandardCharsets

/**
 * Adaptador de [com.example.sgva.domain.DocumentParserPort] para archivos `.csv`,
 * implementado sobre FastCSV (`DESIGN_SGVA.md` §4, adaptador «OpenCsvParser» del
 * diseño; se usa FastCSV por ser una dependencia sin transitivas y gestionable
 * dentro del stack de Spring Boot 4).
 *
 * Se lee la primera fila no vacía como encabezado; la normalización de los
 * valores la aplica [ParserDocumentalBase] a través de los mapeadores.
 */
@Component
internal class CsvDocumentParser : ParserDocumentalBase() {

    override fun soporta(nombreArchivo: String): Boolean = extension(nombreArchivo) == "csv"

    override fun leerTabla(contenido: ByteArray): TablaCruda {
        val registros = CsvReader.builder()
            .skipEmptyLines(true)
            .ofCsvRecord(ByteArrayInputStream(contenido), StandardCharsets.UTF_8)
            .use { lector -> lector.map { it.fields } }

        if (registros.isEmpty()) {
            throw FormatoArchivoInvalidoException("El archivo CSV no contiene ninguna fila.")
        }

        return TablaCruda(
            encabezados = registros.first().map(String::trim),
            filas = registros.drop(1),
        )
    }

    private fun extension(nombreArchivo: String): String =
        nombreArchivo.substringAfterLast('.', "").lowercase()
}

package com.example.sgva.infrastructure.parsing

import com.example.sgva.domain.FormatoArchivoInvalidoException
import org.apache.poi.ss.usermodel.Cell
import org.apache.poi.ss.usermodel.CellType
import org.apache.poi.ss.usermodel.Row
import org.apache.poi.xssf.usermodel.XSSFWorkbook
import org.springframework.stereotype.Component
import java.io.ByteArrayInputStream

/**
 * Adaptador de [com.example.sgva.domain.DocumentParserPort] para archivos `.xlsx`,
 * implementado sobre Apache POI (`DESIGN_SGVA.md` §4, adaptador «ApachePoiExcelParser»).
 *
 * Se procesa la primera hoja del libro: la primera fila es el encabezado y el
 * resto son datos. Las celdas numéricas se convierten a texto sin el `.0` que
 * añade Excel a los enteros; la normalización final la aplica [ParserDocumentalBase].
 */
@Component
internal class ExcelDocumentParser : ParserDocumentalBase() {

    override fun soporta(nombreArchivo: String): Boolean =
        nombreArchivo.substringAfterLast('.', "").lowercase() == "xlsx"

    override fun leerTabla(contenido: ByteArray): TablaCruda =
        XSSFWorkbook(ByteArrayInputStream(contenido)).use { libro ->
            if (libro.numberOfSheets == 0) {
                throw FormatoArchivoInvalidoException("El archivo Excel no contiene ninguna hoja.")
            }

            val filas = libro.getSheetAt(0).iterator().asSequence().toList()
            if (filas.isEmpty()) {
                throw FormatoArchivoInvalidoException("La primera hoja del archivo Excel está vacía.")
            }

            val encabezados = leerFila(filas.first()).map(String::trim)
            TablaCruda(
                encabezados = encabezados,
                filas = filas.drop(1)
                    .map { leerFila(it, encabezados.size) }
                    .filter { valores -> valores.any { it.isNotBlank() } },
            )
        }

    private fun leerFila(fila: Row, columnasMinimas: Int = 0): List<String> {
        val columnas = maxOf(fila.lastCellNum.toInt(), columnasMinimas)
        return (0 until columnas).map { indice ->
            valorComoTexto(fila.getCell(indice, Row.MissingCellPolicy.RETURN_BLANK_AS_NULL))
        }
    }

    private fun valorComoTexto(celda: Cell?): String = when {
        celda == null -> ""
        celda.cellType == CellType.STRING -> celda.stringCellValue.trim()
        celda.cellType == CellType.BOOLEAN -> celda.booleanCellValue.toString()
        celda.cellType == CellType.NUMERIC -> numeroComoTexto(celda.numericCellValue)
        celda.cellType == CellType.FORMULA -> when (celda.cachedFormulaResultType) {
            CellType.STRING -> celda.stringCellValue.trim()
            CellType.NUMERIC -> numeroComoTexto(celda.numericCellValue)
            CellType.BOOLEAN -> celda.booleanCellValue.toString()
            else -> ""
        }
        else -> ""
    }

    private fun numeroComoTexto(valor: Double): String =
        if (valor % 1.0 == 0.0) valor.toLong().toString() else valor.toString()
}

package com.example.sgva.infrastructure.persistence

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.Docente
import com.example.sgva.domain.Estudiante
import org.springframework.stereotype.Repository
import java.util.Collections

/**
 * Adaptador de salida en memoria para [AcademicDataRepository].
 *
 * Es la implementación de persistencia de esta versión: mantiene las entidades
 * en mapas dentro del heap de la JVM, sin durabilidad entre ejecuciones. Se
 * puede reemplazar por un adaptador Spring Data sin tocar el dominio ni los
 * casos de uso (`DESIGN_SGVA.md` §3–§4).
 *
 * Se usa un [LinkedHashMap] sincronizado para preservar el orden de inserción,
 * de modo que los listados sean deterministas para las pruebas y para los
 * gráficos del Dashboard.
 */
@Repository
class AcademicDataRepositoryEnMemoria : AcademicDataRepository {

    private val estudiantesPorId: MutableMap<String, Estudiante> =
        Collections.synchronizedMap(LinkedHashMap())

    private val docentesPorId: MutableMap<String, Docente> =
        Collections.synchronizedMap(LinkedHashMap())

    override fun guardarEstudiante(estudiante: Estudiante): Estudiante {
        estudiantesPorId[estudiante.id] = estudiante
        return estudiante
    }

    override fun buscarEstudiantePorId(id: String): Estudiante? = estudiantesPorId[id]

    override fun listarEstudiantes(): List<Estudiante> =
        synchronized(estudiantesPorId) { estudiantesPorId.values.toList() }

    override fun guardarDocente(docente: Docente): Docente {
        docentesPorId[docente.id] = docente
        return docente
    }

    override fun buscarDocentePorId(id: String): Docente? = docentesPorId[id]

    override fun listarDocentes(): List<Docente> =
        synchronized(docentesPorId) { docentesPorId.values.toList() }
}

