            if (reporte.indicadores.isEmpty()) {
                lienzo.linea("No hay indicadores disponibles.")
            } else {
                lienzo.tabla(
                    encabezados = listOf("Nombre", "Valor", "Periodo", "Facultad"),
                    anchos = listOf(220f, 70f, 90f, 120f),
                    filas = reporte.indicadores.map {
